files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f0;
  --accent: #ff6b6b;
  --bar-bg: #3a3a55;
  --hunger: #f9ca24;
  --happiness: #6ab04c;
  --energy: #22a6b3;
  --border-radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}

h1 {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--accent);
}

.pet {
  width: 120px;
  height: 120px;
  position: relative;
  animation: bounce 2s infinite ease-in-out;
}

@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

.pet-body {
  width: 100%;
  height: 100%;
  background: #ffb347;
  border-radius: 50% 50% 45% 45%;
  position: relative;
  box-shadow: inset -4px -4px 0 #e6952e, 0 4px 8px rgba(0,0,0,0.3);
}

.pet-eye {
  width: 16px;
  height: 16px;
  background: #1e1e2f;
  border-radius: 50%;
  position: absolute;
  top: 40px;
}

.pet-eye.left { left: 28px; }
.pet-eye.right { right: 28px; }

.pet-mouth {
  width: 24px;
  height: 12px;
  border-bottom: 4px solid #1e1e2f;
  border-radius: 0 0 50% 50%;
  position: absolute;
  bottom: 30px;
  left: 50%;
  transform: translateX(-50%);
}

.mood {
  font-size: 18px;
  font-weight: 600;
  color: var(--accent);
}

.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stat-label {
  font-size: 16px;
  font-weight: 500;
}

.bar-bg {
  background: var(--bar-bg);
  border-radius: 8px;
  height: 20px;
  overflow: hidden;
}

.bar {
  height: 100%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.bar.hunger { background: var(--hunger); }
.bar.happiness { background: var(--happiness); }
.bar.energy { background: var(--energy); }

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

button {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 18px;
  font-weight: 600;
  font-family: var(--font);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-width: 80px;
}

button:hover {
  background: #ff5252;
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
  background: #e04848;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  button {
    padding: 10px 16px;
    font-size: 16px;
    min-width: 70px;
  }
}

const state = {
  hunger: 100,
  happiness: 100,
  energy: 100
};

const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');
const moodText = document.getElementById('mood');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  hungerBar.style.width = state.hunger + '%';
  happinessBar.style.width = state.happiness + '%';
  energyBar.style.width = state.energy + '%';

  let mood = 'Happy';
  if (state.hunger < 30 || state.happiness < 30 || state.energy < 30) {
    mood = 'Sad';
  }
  if (state.hunger < 10 || state.happiness < 10 || state.energy < 10) {
    mood = 'Critical';
  }
  moodText.textContent = 'Mood: ' + mood;
}

function feed() {
  state.hunger = clamp(state.hunger + 20);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 30);
  state.hunger = clamp(state.hunger - 10);
  state.happiness = clamp(state.happiness - 5);
  updateUI();
}

document.getElementById('feed').addEventListener('click', feed);
document.getElementById('play').addEventListener('click', play);
document.getElementById('sleep').addEventListener('click', sleep);

updateUI();
